<main class="content container-fluid"><div class="page-toolbar"><a class="btn btn-outline-secondary" href="<?=url($type==='test'?'/admin/tests':'/admin/talleres-asincronicos')?>">← Volver a <?=$type==='test'?'tests':'tabuladores'?></a></div><section class="card panel-card form-card mx-auto"><div class="card-body p-4 p-lg-5"><span class="eyebrow"><?=$type==='test'?'MÓDULO DE TESTS':'MÓDULO DE TALLERES ASINCRÓNICOS'?></span><h2 class="mt-2 mb-1"><?=$resource?'Editar':'Crear nuevo'?> <?=$type==='test'?'test':'tabulador'?></h2><p class="text-secondary mb-4">Registra la información y adjunta un archivo o enlace externo.</p><form method="post" enctype="multipart/form-data" action="<?=url('/admin/recursos/guardar')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($resource['id']??'')?>"><input type="hidden" name="type" value="<?=$type?>"><div class="row g-4"><div class="col-12"><label class="form-label">Nombre</label><input class="form-control" required name="name" value="<?=e($resource['name']??'')?>"></div><div class="col-12"><label class="form-label">Descripción</label><textarea class="form-control" name="description" rows="5"><?=e($resource['description']??'')?></textarea></div><div class="col-md-6"><label class="form-label">Asignatura</label><select class="form-select" name="subject_id"><option value="">Todas las asignaturas</option><?php foreach($subjects as $s):?><option value="<?=$s['id']?>" <?=($resource['subject_id']??null)==$s['id']?'selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></div><?php if($type==='tabulador'):?><div class="col-md-6"><label class="form-label">Grupo</label><select class="form-select" name="group_id"><option value="">Sin grupo</option><?php foreach($groups as $g):?><option value="<?=$g['id']?>" <?=($resource['group_id']??null)==$g['id']?'selected':''?>><?=e($g['name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Subgrupo</label><select class="form-select" name="subgroup_id"><option value="">Sin subgrupo</option><?php foreach($subgroups as $s):?><option value="<?=$s['id']?>" <?=($resource['subgroup_id']??null)==$s['id']?'selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></div><?php else:?><input type="hidden" name="group_id" value=""><input type="hidden" name="subgroup_id" value=""><?php endif;?><div class="col-md-6"><label class="form-label">Archivo</label><input class="form-control" type="file" name="file"><?php if(!empty($resource['file_path'])):?><div class="form-text">Archivo actual: <?=e($resource['file_path'])?></div><?php endif;?></div><div class="col-12"><label class="form-label">Enlace externo</label><input class="form-control" type="url" name="external_link" value="<?=e($resource['external_link']??'')?>" placeholder="https://..."></div><div class="col-12"><input type="hidden" name="active" value="0"><div class="form-check form-switch permission-check"><input class="form-check-input" type="checkbox" role="switch" id="active" name="active" value="1" <?=!isset($resource['active'])||$resource['active']?'checked':''?>><label class="form-check-label" for="active"><strong>Recurso activo y visible</strong><span>Los docentes autorizados podrán verlo.</span></label></div></div></div><div class="form-footer"><a class="btn btn-outline-secondary" href="<?=url($type==='test'?'/admin/tests':'/admin/talleres-asincronicos')?>">Cancelar</a><button class="btn btn-brand" type="submit">Guardar recurso</button></div></form></div></section></main>
